#!/usr/bin/env bash
# Build the ESP-Hosted 2.13.1 slave firmware for the Tab5's ESP32-C6.
#
# This copies the slave project out of the host component so the build does
# not modify firmware/managed_components (which is regenerated by idf.py).
# Run it from an ESP-IDF 5.4 environment, after the host project has fetched
# espressif/esp_hosted 2.13.1 once.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
HOSTED="$ROOT/firmware/managed_components/espressif__esp_hosted"
WORK="$ROOT/tools/c6_firmware/build"
SRC="$WORK/src"

if [[ ! -d "$HOSTED/slave" || ! -d "$HOSTED/common" ]]; then
    echo "esp_hosted component not found under $HOSTED" >&2
    echo "Run 'idf.py reconfigure' in firmware/ first to fetch it." >&2
    exit 1
fi
if [[ -z "${IDF_PATH:-}" ]]; then
    echo "IDF_PATH is not set; source the ESP-IDF 5.4 export script first." >&2
    exit 1
fi

rm -rf "$SRC"
mkdir -p "$SRC"
cp -a "$HOSTED/slave" "$SRC/slave"
cp -a "$HOSTED/common" "$SRC/common"

cat >> "$SRC/slave/sdkconfig.defaults" <<'EOF'

# M5Stack Tab5 onboard ESP32-C6 module
# CONFIG_ESP_HOST_DEV_BOARD_NONE is not set
CONFIG_ESP32P4_TAB5_C6_BOARD=y
EOF

cd "$SRC/slave"
idf.py set-target esp32c6
idf.py build

cp build/bootloader/bootloader.bin "$ROOT/tools/c6_firmware/"
cp build/partition_table/partition-table.bin "$ROOT/tools/c6_firmware/"
cp build/ota_data_initial.bin "$ROOT/tools/c6_firmware/"
cp build/network_adapter.bin "$ROOT/tools/c6_firmware/"

cd "$ROOT/tools/c6_firmware"
sha256sum bootloader.bin partition-table.bin ota_data_initial.bin network_adapter.bin \
    > SHA256SUMS
echo "C6 firmware copied to $ROOT/tools/c6_firmware"
